INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do I need to book?', 'Walk-ins are welcome when stations are free. Booking guarantees your station, especially in the evenings and at weekends.', 0),
  ('Is there an age limit?', 'Everyone is welcome during the day. Under-13s should come with an adult, and age ratings apply to some games.', 1),
  ('Can I bring my own controller or account?', 'Yes, you can bring your own controller and log in to your own accounts.', 2),
  ('How do tournaments work?', 'Register before the deadline, pay the entry fee if there is one, and show up on time. Rules are shared before each event.', 3),
  ('Do you host birthday parties?', 'Yes. Ask about our private room and party packages.', 4);
